# Load staging tables
# Tables the transform always produces one row per case for
CORE_TABLES = ["S62aCase", "S62aDates", "S62aFees", "Contact", "Address", "S62aCaseLpa"]
OPTIONAL_TABLES = ["S62aCaseTotals", "S62aCaseInspector", "S62aEvent", "S62aVehicleParking",
                   "S62aNonResidentialFloorspace", "S62aResidentialHousing", "S62aCaseWasteType", "S62aCaseNote"]
TABLES = CORE_TABLES + OPTIONAL_TABLES
FLAT_TABLES = ["S62aCase", "S62aDates", "S62aFees"]

def read_table(name):
    """Returns (DataFrame or None if the file is missing, raw_row_count)."""
    try:
        path = fetch(f"{STAGING_DIR}/{name}.csv")
        if not os.path.exists(path):
            return None
    except Exception as e:
        print(f"  {name}: not found ({type(e).__name__})")
        return None
    kw = dict(dtype=str, keep_default_na=False)
    try:
        df = pd.read_csv(path, **kw)
    except pd.errors.EmptyDataError:
        return pd.DataFrame()
    except pd.errors.ParserError as e:
        flag("ERROR", "csv_malformed", None, name, None, "consistent column count", None, str(e)[:200])
        df = pd.read_csv(path, engine="python", on_bad_lines="skip", **kw)
    return df.replace({"": None})

stg = {}
for t in TABLES:
    df = read_table(t)
    if df is None:
        flag("ERROR" if t in CORE_TABLES else "WARN", "table_missing", None, t, None, f"{t}.csv", None,
             "File not written by s62a_transform")
    else:
        stg[t] = df

summary_df = read_table("_summary")
exceptions_df = read_table("_exceptions")

for t, df in stg.items():
    print(f"  {t:30} {len(df):>5} rows | {len(df.columns):>3} columns")

if "S62aCase" not in stg or stg["S62aCase"].empty:
    flag("ERROR", "no_cases", None, "S62aCase", None, ">0 rows", 0, "No cases in staging, nothing to process downstream")

# 1. Structure: file vs transform summary, headers, required and expected columns
if summary_df is not None and not summary_df.empty:
    for _, r in summary_df.iterrows():
        t = r["table"]
        if int(r["rows"]) > 0 and t in TABLES and t not in stg:
            continue  # already flagged as missing
        actual = len(stg[t]) if t in stg else 0
        if t in TABLES and int(r["rows"]) != actual:
            flag("ERROR", "row_count_mismatch", None, t, None, r["rows"], actual, "Rows written differ from _summary.csv (truncated or corrupt file)")
        elif t in TABLES and int(r["columns"]) != (len(stg[t].columns) if t in stg else 0) and actual:
            flag("ERROR", "column_count_mismatch", None, t, None, r["columns"], len(stg[t].columns), "Columns written differ from _summary.csv")
else:
    flag("WARN", "summary_missing", None, "_summary", None, "present", None, "Cannot cross-check row counts")

BASE_COLUMNS = {"S62aCase": ["id", "caseReference"]}
CHILD_BASE = ["id", "caseId", "caseReference"]
TABLE_COLUMNS = {
    "S62aCase":          ["description", "S62aStatus"],
    "Contact":           ["contactRole", "sequence", "firstName", "lastName", "email", "telephoneNumber"],
    "Address":           ["addressType", "line1", "townCity", "postcode"],
    "S62aCaseLpa":       ["lpaRole", "lpa", "lpaId"],
    "S62aCaseInspector": ["inspectorNumber", "user"],
    "S62aCaseNote":      ["noteType", "noteText"],
    "S62aResidentialHousing": ["housingType", "groupId"],
}

# Expected flat-table columns come from the mapping file
SPECIAL = {"Case reference", "Pre-application status", "Application Status", "Pre-app/Application received date"}
mapped_cols = {t: set() for t in FLAT_TABLES}
try:
    mapping = pd.read_excel(fetch(MAPPING_FILE), sheet_name=0, dtype=str)
    mapping.columns = ["source_column", "target_field", "target_table", "notes"][:len(mapping.columns)]
    for c in ["source_column", "target_field", "target_table"]:
        mapping[c] = mapping[c].astype(str).str.strip().replace("nan", None)
    fm = mapping[mapping.target_table.isin(FLAT_TABLES) & mapping.target_field.notna()]
    fm = fm[(fm.target_field != "Notes") & ~fm.source_column.isin(SPECIAL)]
    for _, m in fm.iterrows():
        mapped_cols[m.target_table].add(re.sub(r"\s+", "", m.target_field))
except Exception as e:
    flag("WARN", "mapping_unavailable", None, None, None, MAPPING_FILE, None, f"Mapped columns not checked: {type(e).__name__}")

for t, df in stg.items():
    if not len(df.columns):
        continue
    required = BASE_COLUMNS.get(t, CHILD_BASE) + TABLE_COLUMNS.get(t, []) + sorted(mapped_cols.get(t, []))
    for c in dict.fromkeys(required):
        if c not in df.columns:
            flag("ERROR", "column_missing", None, t, c, c, None, "Expected column not in staging output")
    for c in df.columns:
        if str(c).startswith("Unnamed:") or not str(c).strip():
            flag("ERROR", "column_unnamed", None, t, c, "named column", c)
        elif re.search(r"\.\d+$", str(c)) and re.sub(r"\.\d+$", "", str(c)) in df.columns:
            flag("ERROR", "column_duplicate", None, t, c, "unique column names", c)
        elif c != str(c).strip():
            flag("WARN", "column_whitespace", None, t, repr(c), "no surrounding whitespace", c)
    empty_rows = df.drop(columns=[c for c in ("id", "caseId", "caseReference") if c in df.columns]).isna().all(axis=1)
    for i in df.index[empty_rows]:
        flag("WARN", "row_empty", df.at[i, "caseReference"] if "caseReference" in df.columns else None, t, None, "some data", None, f"Row {i + 2} has only keys")
print(f"Structure issues so far: {len(issues)}")

# 2. Data types, formats and allowed values
GUID_COLUMNS = ["id", "caseId", "lpaId"]
INT_COLUMNS  = {"Contact": ["sequence"], "S62aCaseInspector": ["inspectorNumber"]}
NUMERIC_COLUMNS = {
    "S62aCase": ["siteEasting", "siteNorthing", "siteAreaInSquareMetres", "cilAmount", "pressNoticeCost"],
    "S62aFees": ["preApplicationFee", "applicationFee", "applicationFeeRefundAmount"],
    "S62aCaseTotals": ["totalProposedResidentialUnits", "netResidentialUnitChange", "netAdditionalFloorspaceSqM",
                       "nonResExistingFloorspaceSqM", "nonResFloorspaceLostSqM", "nonResFloorspaceProposedSqM",
                       "nonResNetFloorspaceSqM"],
    "S62aVehicleParking": ["existingSpaces", "proposedSpaces", "spaceDifference"],
    "S62aNonResidentialFloorspace": ["netAdditionalGross", "existingGross", "grossLost", "grossProposed"],
    "S62aResidentialHousing": ["bedroomsOne", "bedroomsTwo", "bedroomsThree", "bedroomsFourPlus", "bedroomsUnknown", "totalUnits"],
}
BOOL_COLUMNS = {"S62aCase": ["eiaScreening", "isGreenBelt", "cilLiable", "bngExempt", "siteIsVisibleFromPublicLand",
                             "isWasteManagementDevelopment"]}
BOOL_VALUES  = {"yes", "no", "y", "n", "true", "false", "1", "0"}
EMAIL_COLUMNS = {"Contact": ["email"], "S62aCaseLpa": ["email"]}
ENUMS = {("Contact", "contactRole"): {"Agent", "Applicant"},
         ("Address", "addressType"): {"Agent", "Applicant", "Site"},
         ("S62aCaseLpa", "lpaRole"): {"Primary", "Secondary"},
         ("S62aResidentialHousing", "housingType"): {"Existing", "Proposed"},
         ("S62aCaseInspector", "inspectorNumber"): {"1", "2", "3"}}
REQUIRED_VALUES = {  # (column, severity) - must not be blank
    "S62aCase": [("caseReference", "ERROR"), ("description", "ERROR")],
    "Contact": [("contactRole", "ERROR")], "Address": [("addressType", "ERROR")],
    "S62aCaseLpa": [("lpaRole", "ERROR"), ("lpaId", "ERROR")],
    "S62aCaseInspector": [("user", "WARN")], "S62aCaseNote": [("noteType", "ERROR"), ("noteText", "ERROR")],
}
CASE_REF_RE = re.compile(r"^S62A/\d{4}/\d{7}(RD)?$")
EMAIL_RE    = re.compile(r"^[^@\s;,]+@[^@\s;,]+\.[a-z]{2,}$", re.I)
floor = pd.Timestamp(MIN_VALID_DATE)

def present(df, c):
    return c in df.columns

for t, df in stg.items():
    if df.empty:
        continue
    for c in [c for c in ("id", "caseId", "caseReference") if present(df, c) and not (t == "S62aCase" and c == "caseId")]:
        flag_cells(df, df[c].isna(), t, c, "ERROR", "key_empty", "value")

    for c in GUID_COLUMNS:
        if present(df, c):
            def bad_guid(v):
                try:
                    uuid.UUID(str(v)); return False
                except ValueError:
                    return True
            flag_cells(df, df[c].notna() & df[c].map(lambda v: v is not None and bad_guid(v)), t, c, "ERROR", "guid_invalid", "GUID")

    if present(df, "caseReference"):
        s = df["caseReference"]
        flag_cells(df, s.notna() & ~s.fillna("").str.match(CASE_REF_RE), t, "caseReference", "ERROR", "case_reference_format", "S62A/YYYY/NNNNNNN")

    for c in [c for c in df.columns if re.search(r"date$", str(c), re.I)]:
        s = df[c]
        fmt_ok = s.fillna("").str.match(r"^\d{4}-\d{2}-\d{2}$")
        parsed = pd.to_datetime(s.where(fmt_ok), format="%Y-%m-%d", errors="coerce")
        flag_cells(df, s.notna() & (~fmt_ok | parsed.isna()), t, c, "ERROR", "date_format", "YYYY-MM-DD")
        flag_cells(df, parsed.notna() & (parsed < floor), t, c, "WARN", "date_too_old", f">= {MIN_VALID_DATE}")

    for c in INT_COLUMNS.get(t, []):
        if present(df, c):
            flag_cells(df, df[c].notna() & ~df[c].fillna("").str.match(r"^\d+$"), t, c, "ERROR", "not_integer", "whole number")

    for c in NUMERIC_COLUMNS.get(t, []):
        if present(df, c):
            num = pd.to_numeric(df[c].fillna("").str.replace(r"[£,\s]", "", regex=True).replace("", None), errors="coerce")
            flag_cells(df, df[c].notna() & num.isna(), t, c, "WARN", "not_numeric", "number", "Schema align will set this to null")

    for c in BOOL_COLUMNS.get(t, []):
        if present(df, c):
            flag_cells(df, df[c].notna() & ~df[c].fillna("").str.strip().str.lower().isin(BOOL_VALUES), t, c, "WARN", "not_boolean", "yes/no", "Schema align will set this to null")

    for c in EMAIL_COLUMNS.get(t, []):
        if present(df, c):
            s = df[c]
            flag_cells(df, s.notna() & ~s.fillna("").map(lambda v: bool(EMAIL_RE.match(v))), t, c, "WARN", "email_invalid", "name@domain")

    for (et, c), allowed in ENUMS.items():
        if et == t and present(df, c):
            flag_cells(df, df[c].notna() & ~df[c].isin(allowed), t, c, "ERROR", "value_not_allowed", sorted(allowed))

    for c, sev in REQUIRED_VALUES.get(t, []):
        if present(df, c):
            flag_cells(df, df[c].isna(), t, c, sev, "required_field_empty", "value", "Downstream stages need this value")
print(f"Issues after type checks: {len(issues)}")

# 3. Malformed records: placeholder text, stray characters, broken multi-value cells
PLACEHOLDERS = {"nan", "nat", "none", "null", "#n/a", "#ref!", "#value!", "#div/0!", "#name?", "#num!"}
SKIP = {"id", "caseId", "caseReference"}

for t, df in stg.items():
    if df.empty:
        continue
    for c in [c for c in df.columns if c not in SKIP]:
        s = df[c].dropna()
        if s.empty:
            continue
        low = s.str.strip().str.lower()
        flag_cells(df, low.isin(PLACEHOLDERS).reindex(df.index), t, c, "WARN", "placeholder_text", "value or empty", "Looks like a spreadsheet/pandas placeholder")
        flag_cells(df, (s != s.str.strip()).reindex(df.index), t, c, "WARN", "surrounding_whitespace", "trimmed text")
        flag_cells(df, s.str.contains(r"[\r\n]", regex=True).reindex(df.index), t, c, "WARN", "line_break_in_value", "single line", "Transform should flatten line breaks")
        flag_cells(df, s.str.contains("\ufffd", regex=False).reindex(df.index), t, c, "ERROR", "encoding_corruption", "valid text", "Contains replacement character")
        flag_cells(df, s.str.contains(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", regex=True).reindex(df.index), t, c, "ERROR", "control_character", "printable text")
        unbalanced = (s.str.count(r"\[") != s.str.count(r"\]")) | (s.str.count(r"\{") != s.str.count(r"\}"))
        flag_cells(df, unbalanced.reindex(df.index), t, c, "WARN", "unbalanced_brackets", "balanced [ ] / { }", "Multi-value cell may have been split wrongly")

# Rows the transform itself flagged as needing action
if exceptions_df is not None and not exceptions_df.empty and "severity" in exceptions_df.columns:
    for issue, g in exceptions_df[exceptions_df.severity == "ACTION"].groupby("issue"):
        flag("WARN", "transform_action", None, g["table"].iloc[0], g["column"].iloc[0], None, len(g), f"{issue} ({g['caseReference'].nunique()} cases)")
print(f"Issues after malformed-record checks: {len(issues)}")

# 4. Keys and relationships between staging tables
cases = stg.get("S62aCase", pd.DataFrame())
if not cases.empty and {"id", "caseReference"} <= set(cases.columns):
    for c in ("id", "caseReference"):
        for v in cases.loc[cases[c].notna() & cases[c].duplicated(keep=False), c].unique():
            flag("ERROR", "duplicate_key", v if c == "caseReference" else None, "S62aCase", c, "unique", v)
    id_to_ref = dict(zip(cases["id"], cases["caseReference"]))

    for t, df in stg.items():
        if t == "S62aCase" or df.empty:
            continue
        if present(df, "id"):
            for v in df.loc[df["id"].notna() & df["id"].duplicated(keep=False), "id"].unique():
                flag("ERROR", "duplicate_key", None, t, "id", "unique", v)
        if present(df, "caseId"):
            orphan = df["caseId"].notna() & ~df["caseId"].isin(id_to_ref)
            flag_cells(df, orphan, t, "caseId", "ERROR", "orphan_row", "id in S62aCase", "No parent case")
            if present(df, "caseReference"):
                mism = df["caseId"].isin(id_to_ref) & (df["caseId"].map(id_to_ref) != df["caseReference"])
                flag_cells(df, mism, t, "caseId", "ERROR", "case_id_reference_mismatch", None, "caseId points at a different case than caseReference")

    for t in ("S62aDates", "S62aFees", "S62aCaseTotals"):
        df = stg.get(t)
        if df is not None and not df.empty and present(df, "caseReference"):
            for v in df.loc[df["caseReference"].duplicated(keep=False), "caseReference"].dropna().unique():
                flag("ERROR", "not_one_to_one", v, t, "caseReference", 1, ">1", "More than one row for a 1:1 table")

    for t in ("S62aDates", "S62aFees"):
        df = stg.get(t)
        got = set(df["caseReference"].dropna()) if df is not None and not df.empty and present(df, "caseReference") else set()
        for ref in sorted(set(cases["caseReference"].dropna()) - got):
            flag("ERROR", "case_row_missing", ref, t, None, "row", None, "Case has no row in this 1:1 table")

    for c in ("Contact", "S62aCaseLpa"):
        df = stg.get(c)
        got = set(df["caseReference"].dropna()) if df is not None and not df.empty and present(df, "caseReference") else set()
        for ref in sorted(set(cases["caseReference"].dropna()) - got):
            flag("WARN", "case_without_rows", ref, c, None, "at least one row", 0)

print(f"Issues after key checks: {len(issues)}")

# Write outputs
files = {"_validation_issues.csv": issues_df, "_validation_summary.csv": summary}
out_dir = os.path.join(TMP if not LOCAL_DIR else ".", f"s62a_staging_validation_{RUN_TS}")
os.makedirs(out_dir, exist_ok=True)
for name, frame in files.items():
    frame.to_csv(os.path.join(out_dir, name), index=False, encoding="utf-8", quoting=csv.QUOTE_MINIMAL)

if LOCAL_DIR:
    print(f"Written to {out_dir}")
else:
    for folder in (RUN_TS, "latest"):
        dest = f"{ROOT}/{OUTPUT_DIR}/{folder}"
        if folder == "latest":
            try:
                mssparkutils.fs.rm(dest, True)
            except Exception:
                pass
        for name in files:
            mssparkutils.fs.cp(f"file:{os.path.join(out_dir, name)}", f"{dest}/{name}")
        print(f"Written to {dest}")

# Stops the pipeline here so USER, SCHEMA ALIGN and DOCUMENT don't run on invalid data
if FAIL_ON_ERROR and n_err:
    raise Exception(f"s62a staging validation failed: {n_err} errors across {bad_cases} cases, "
                    f"see {OUTPUT_DIR}/latest/_validation_issues.csv")
